import "leaflet/dist/leaflet.css";
import L from "leaflet";
import { Link } from "react-router-dom";
import propertiesData from "../data/properties";

// =======================
// CONFIG ICONOS LEAFLET
// =======================
delete L.Icon.Default.prototype._getIconUrl;

L.Icon.Default.mergeOptions({
  iconRetinaUrl: require("leaflet/dist/images/marker-icon-2x.png"),
  iconUrl: require("leaflet/dist/images/marker-icon.png"),
  shadowUrl: require("leaflet/dist/images/marker-shadow.png"),
});

// =======================
// LOCATION SELECTOR
// =======================
function LocationSelector({ setPosition }) {
  useMapEvents({
    click(e) {
      setPosition(e.latlng);
    },
  });

  return null;
}

export default function Publish() {
  const [properties, setProperties] = useState(propertiesData);

  // =======================
  // DARK MODE
  // =======================
  const [darkMode, setDarkMode] = useState(
    localStorage.getItem("theme") === "dark"
  );

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add("dark");
      localStorage.setItem("theme", "dark");
    } else {
      document.documentElement.classList.remove("dark");
      localStorage.setItem("theme", "light");
    }
  }, [darkMode]);

  // =======================
  // FORM STATE
  // =======================
  const [form, setForm] = useState({
    title: "",
    price: "",
    description: "",
    type: "Apartamento",
    status: "Venta",
    rooms: 1,
    baths: 1,
    parking: 1,
    image: "",
    lat: "",
    lng: "",
  });

  const [position, setPosition] = useState(null);

  // =======================
  // FAVORITOS
  // =======================
  const toggleLike = (id) => {
    const updated = properties.map((p) =>
      p.id === id ? { ...p, liked: !p.liked } : p
    );

    setProperties(updated);
  };

  // =======================
  // IMAGE UPLOAD
  // =======================
  const handleImageUpload = (e) => {
    const file = e.target.files[0];

    if (!file) return;

    const reader = new FileReader();

    reader.onloadend = () => {
      setForm({ ...form, image: reader.result });
    };

    reader.readAsDataURL(file);
  };

  // =======================
  // SUBMIT
  // =======================
  const handleSubmit = (e) => {
    e.preventDefault();

    let lat = position?.lat;
    let lng = position?.lng;

    if (!lat || !lng) {
      if (!form.lat || !form.lng)
        return alert("Ubicación requerida");

      lat = parseFloat(form.lat);
      lng = parseFloat(form.lng);
    }

    const newProperty = {
      id: Date.now(),
      ...form,
      lat,
      lng,
      liked: false,
    };

    setProperties([...properties, newProperty]);

    setForm({
      title: "",
      price: "",
      description: "",
      type: "Apartamento",
      status: "Venta",
      rooms: 1,
      baths: 1,
      parking: 1,
      image: "",
      lat: "",
      lng: "",
    });

    setPosition(null);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-100 to-gray-200 dark:from-gray-900 dark:to-black dark:text-white transition-colors duration-300">

      {/* NAVBAR */}
      <div className="sticky top-0 z-50 backdrop-blur-md bg-white/80 dark:bg-gray-900/80 border-b border-gray-200 dark:border-gray-700 shadow-sm">

        <div className="max-w-7xl mx-auto px-4 py-3 flex items-center justify-between">

          {/* LOGO */}
          <div className="flex items-center gap-2">

            <div className="bg-blue-600 text-white w-10 h-10 rounded-2xl flex items-center justify-center text-xl shadow-md">
              🏠
            </div>

            <div>
              <h1 className="font-black text-xl leading-none">
                DomusRD
              </h1>

              <p className="text-xs text-gray-500 dark:text-gray-400">
                Publicar Propiedad
              </p>
            </div>

          </div>

          {/* MENU */}
          <div className="flex items-center gap-3">

            {/* DARK MODE */}
            <button
              onClick={() => setDarkMode(!darkMode)}
              className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 px-4 py-2 rounded-full hover:shadow-md transition"
            >
              {darkMode ? "☀️" : "🌙"}
            </button>

            {/* HOME */}
            <Link to="/">
              <button className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 px-4 py-2 rounded-full hover:shadow-md transition">
                🏡 Inicio
              </button>
            </Link>

            {/* SIGN IN */}
            <button className="bg-gray-900 text-white px-4 py-2 rounded-full hover:bg-black transition">
              👤 Sign In
            </button>

          </div>

        </div>

      </div>

      {/* CONTENIDO */}
      <div className="max-w-7xl mx-auto p-4 md:p-6">

        <div className="grid grid-cols-1 xl:grid-cols-3 gap-6 items-start">

          {/* MAPA */}
          <div className="xl:col-span-2">

            <MapContainer
              center={[18.7357, -70.1627]}
              zoom={7.5}
              scrollWheelZoom={false}
              className="
                h-[450px]
                md:h-[500px]
                rounded-3xl
                shadow-2xl
                overflow-hidden
                border
                border-gray-200
                dark:border-gray-700
              "
              style={{ zIndex: 0 }}
            >

              <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />

              {properties.map((prop) => (
                <Marker
                  key={prop.id}
                  position={[prop.lat, prop.lng]}
                >
                  <Popup>
                    <strong>{prop.title}</strong>

                    <br />

                    ${prop.price}
                  </Popup>
                </Marker>
              ))}

              <LocationSelector setPosition={setPosition} />

              {position && (
                <Marker position={position}>
                  <Popup>Nueva propiedad</Popup>
                </Marker>
              )}

            </MapContainer>

          </div>

          {/* FORM */}
          <form
            onSubmit={handleSubmit}
            className="
              bg-white/90
              dark:bg-gray-900/90
              backdrop-blur-md
              border
              border-gray-200
              dark:border-gray-700
              shadow-2xl
              rounded-3xl
              p-6
              space-y-5
              h-fit
              transition-colors
            "
          >

            <div>

              <h2 className="text-2xl font-black">
                Publicar propiedad
              </h2>

              <p className="text-gray-500 dark:text-gray-400 text-sm">
                Completa la información del inmueble
              </p>

            </div>

            {/* TITULO */}
            <input
              placeholder="Título de la propiedad"
              value={form.title}
              onChange={(e) =>
                setForm({ ...form, title: e.target.value })
              }
              className="
                w-full
                bg-gray-50 dark:bg-gray-800
                border border-gray-200 dark:border-gray-700
                text-black dark:text-white
                rounded-2xl
                px-4 py-3
                outline-none
                focus:ring-2
                focus:ring-blue-500
              "
            />

            {/* PRECIO */}
            <input
              placeholder="Precio"
              value={form.price}
              onChange={(e) =>
                setForm({ ...form, price: e.target.value })
              }
              className="
                w-full
                bg-gray-50 dark:bg-gray-800
                border border-gray-200 dark:border-gray-700
                text-black dark:text-white
                rounded-2xl
                px-4 py-3
                outline-none
                focus:ring-2
                focus:ring-blue-500
              "
            />

            {/* STATUS */}
            <select
              value={form.status}
              onChange={(e) =>
                setForm({ ...form, status: e.target.value })
              }
              className="
                w-full
                bg-gray-50 dark:bg-gray-800
                border border-gray-200 dark:border-gray-700
                text-black dark:text-white
                rounded-2xl
                px-4 py-3
              "
            >
              <option>Venta</option>
              <option>Renta</option>
            </select>

            {/* TIPO */}
            <select
              value={form.type}
              onChange={(e) =>
                setForm({ ...form, type: e.target.value })
              }
              className="
                w-full
                bg-gray-50 dark:bg-gray-800
                border border-gray-200 dark:border-gray-700
                text-black dark:text-white
                rounded-2xl
                px-4 py-3
              "
            >
              <option>Apartamento</option>
              <option>Casa</option>
              <option>Villa</option>
            </select>

            {/* SPECS */}
            <div className="grid grid-cols-3 gap-3">

              <select
                value={form.rooms}
                onChange={(e) =>
                  setForm({ ...form, rooms: e.target.value })
                }
                className="
                  bg-gray-50 dark:bg-gray-800
                  border border-gray-200 dark:border-gray-700
                  text-black dark:text-white
                  rounded-2xl
                  px-3 py-3
                "
              >
                {[1, 2, 3, 4, 5].map((n) => (
                  <option key={n}>
                    {n} hab
                  </option>
                ))}
              </select>

              <select
                value={form.baths}
                onChange={(e) =>
                  setForm({ ...form, baths: e.target.value })
                }
                className="
                  bg-gray-50 dark:bg-gray-800
                  border border-gray-200 dark:border-gray-700
                  text-black dark:text-white
                  rounded-2xl
                  px-3 py-3
                "
              >
                {[1, 2, 3, 4].map((n) => (
                  <option key={n}>
                    {n} baños
                  </option>
                ))}
              </select>

              <select
                value={form.parking}
                onChange={(e) =>
                  setForm({ ...form, parking: e.target.value })
                }
                className="
                  bg-gray-50 dark:bg-gray-800
                  border border-gray-200 dark:border-gray-700
                  text-black dark:text-white
                  rounded-2xl
                  px-3 py-3
                "
              >
                {[0, 1, 2, 3].map((n) => (
                  <option key={n}>
                    {n} parqueos
                  </option>
                ))}
              </select>

            </div>

            {/* DESCRIPCION */}
            <textarea
              placeholder="Descripción"
              value={form.description}
              onChange={(e) =>
                setForm({ ...form, description: e.target.value })
              }
              className="
                w-full
                bg-gray-50 dark:bg-gray-800
                border border-gray-200 dark:border-gray-700
                text-black dark:text-white
                rounded-2xl
                px-4 py-3
                h-28
                resize-none
                outline-none
                focus:ring-2
                focus:ring-blue-500
              "
            />

            {/* FOTO */}
            <div className="border-2 border-dashed border-gray-300 dark:border-gray-700 rounded-2xl p-5 text-center bg-gray-50 dark:bg-gray-800">

              <p className="text-sm text-gray-500 dark:text-gray-400 mb-2">
                📸 Subir imagen
              </p>

              <input
                type="file"
                onChange={handleImageUpload}
                className="w-full"
              />

            </div>

            {/* UBICACION */}
            <div className="bg-blue-50 dark:bg-blue-950/30 border border-blue-100 dark:border-blue-900 rounded-2xl p-4 text-sm text-gray-600 dark:text-gray-300">

              <p className="font-semibold mb-1">
                📍 Ubicación seleccionada
              </p>

              {position ? (
                <>
                  <p>Lat: {position.lat.toFixed(4)}</p>
                  <p>Lng: {position.lng.toFixed(4)}</p>
                </>
              ) : (
                <p>Pulsa en el mapa para seleccionar ubicación</p>
              )}

            </div>

            {/* BOTON */}
            <button
              className="
                w-full
                bg-blue-600
                hover:bg-blue-700
                text-white
                rounded-2xl
                py-4
                font-bold
                shadow-xl
                hover:scale-[1.02]
                active:scale-[0.98]
                transition
                duration-200
              "
            >
              Publicar propiedad
            </button>

          </form>

        </div>

        {/* TITULO FEED */}
        <div className="mt-10 mb-4">

          <h2 className="text-2xl font-black">
            Propiedades publicadas
          </h2>

          <p className="text-gray-500 dark:text-gray-400">
            Visualiza las propiedades disponibles actualmente
          </p>

        </div>

        {/* FEED */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">

          {properties.map((prop) => (

            <div
              key={prop.id}
              className="
                bg-white
                dark:bg-gray-900
                rounded-3xl
                shadow-lg
                dark:shadow-black/30
                overflow-hidden
                hover:shadow-2xl
                transition
                duration-300
                relative
              "
            >

              {/* FAVORITO */}
              <button
                onClick={() => toggleLike(prop.id)}
                className="absolute top-3 right-3 z-20 text-xl"
              >
                {prop.liked ? "❤️" : "🤍"}
              </button>

              {/* STATUS */}
              <div className="absolute top-3 left-3 z-20 bg-white dark:bg-gray-800 px-3 py-1 rounded-full text-sm font-semibold shadow">

                {prop.status || "Venta"}

              </div>

              {/* FOTO */}
              {prop.image && (
                <img
                  src={prop.image}
                  alt={prop.title}
                  className="w-full h-52 object-cover"
                />
              )}

              {/* INFO */}
              <div className="p-5">

                <h3 className="font-bold text-lg">
                  {prop.title}
                </h3>

                <p className="text-blue-600 font-bold text-lg mt-1">
                  ${prop.price}
                </p>

                <p className="text-gray-500 dark:text-gray-400 text-sm mt-2">
                  {prop.type} • {prop.rooms} hab • {prop.baths} baños • {prop.parking} parqueos
                </p>

              </div>

            </div>

          ))}

        </div>

      </div>

    </div>
  );
}
